#!/bin/bash
set -o errexit
set -o nounset
set -o pipefail
# Generated by the write-env step, unavailable during static analysis.
# shellcheck source=/dev/null
source "${SHARED_DIR}/capz-test-env.sh"
# Diagnostics handle secrets below; keep tracing disabled even if invoked with -x.
{ set +o xtrace; } 2>/dev/null

export INIT_KIND=false
export USE_KUBECONFIG="${SHARED_DIR}/kubeconfig"

if [[ -f "${SHARED_DIR}/dev_endpoint" ]]; then
  DEV_ENDPOINT=$(cat "${SHARED_DIR}/dev_endpoint")
  export DEV_ENDPOINT
  export ARO_NULL_PROVISIONING=true
  echo "DEV_ENDPOINT loaded: ${DEV_ENDPOINT}"
fi

if [[ -d "${ARO_REPO_DIR}" ]]; then
  echo "Repository already exists at ${ARO_REPO_DIR}"
else
  echo "Cloning ${ARO_REPO_URL} branch ${ARO_REPO_BRANCH} into ${ARO_REPO_DIR}"
  git clone -b "${ARO_REPO_BRANCH}" "${ARO_REPO_URL}" "${ARO_REPO_DIR}"
fi

# Phase 03: Management Cluster
# With USE_KUBECONFIG set, skips Kind creation and validates the external cluster
# with CAPI/CAPZ/ASO controllers (deployed via DEPLOY_CHARTS=true).
export TEST_RESULTS_DIR="${ARTIFACT_DIR}"
test_status=0
script -e -q -c "make _management_cluster RESULTS_DIR=\"${ARTIFACT_DIR}\"" /dev/null || test_status=$?

# Always diagnose before teardown, including when controller readiness failed.
# Capture kubectl output in memory and suppress raw stderr, which may contain
# registry responses or other sensitive values. Emit fixed comparison results.
diagnostic_status=0
if [[ "${QUAY_AUTH_DIAGNOSTICS:-false}" == "true" ]]; then
python3 - <<'PY_QUAY_DIAGNOSTICS' || diagnostic_status=$?
import base64
import hashlib
import json
import os
from pathlib import Path
import subprocess


def fingerprint(config):
    auth = config["auths"]["quay.io"]["auth"]
    credential = base64.b64decode(auth, validate=True)
    username, separator, token = credential.partition(b":")
    if not username or not separator or not token:
        raise ValueError("invalid credential")
    return hashlib.sha256(credential).hexdigest()


def kube_json(namespace, *args):
    result = subprocess.run(
        ["kubectl", "--kubeconfig", os.environ["USE_KUBECONFIG"],
         "--request-timeout=15s", "-n", namespace, "get", *args, "-o", "json"],
        capture_output=True, text=True, timeout=20, check=True)
    return json.loads(result.stdout)


failed = False
try:
    source = (Path(os.environ["SHARED_DIR"]) / "quay-auth.sha256").read_text().strip()
    environment = fingerprint(json.loads(base64.b64decode(
        os.environ["IMAGE_PULL_SECRET_B64"], validate=True)))
    matches = source == environment
    print("[quay-diag] Prow mount → management environment: " + ("MATCH" if matches else "MISMATCH"))
    failed = not matches
except Exception:
    print("[quay-diag] Prow mount → management environment: INVALID OR MISSING")
    environment = None
    failed = True

for namespace, secret_name, label, controllers in [
        ("capi-system", "capi-manager-pull-credentials", "CAPI",
         ("capi-controller-manager", "mce-capi-webhook-config")),
        ("capz-system", "capz-manager-pull-credentials", "CAPZ",
         ("capz-controller-manager", "azureserviceoperator-controller-manager"))]:
    try:
        secret = kube_json(namespace, "secret", secret_name)
        if secret.get("type") != "kubernetes.io/dockerconfigjson":
            raise ValueError("incorrect secret type")
        deployed = fingerprint(json.loads(base64.b64decode(
            secret["data"][".dockerconfigjson"], validate=True)))
        matches = environment is not None and deployed == environment
        print(f"[quay-diag] environment → {label} pull secret: " + ("MATCH" if matches else "MISMATCH"))
        failed |= not matches
    except Exception:
        print(f"[quay-diag] environment → {label} pull secret: INVALID OR UNREADABLE")
        failed = True
    try:
        pods = kube_json(namespace, "pods")["items"]
        for controller in controllers:
            selected = [pod for pod in pods if pod["metadata"]["name"].startswith(controller + "-")]
            references_match = bool(selected) and all(
                secret_name in [ref["name"] for ref in pod["spec"].get("imagePullSecrets", [])]
                for pod in selected)
            print(f"[quay-diag] {controller} pod pull-secret reference: " +
                  ("PASS" if references_match else "MISSING OR INCORRECT"))
            failed |= not references_match
    except Exception:
        print(f"[quay-diag] {label} pod pull-secret references: UNREADABLE")
        failed = True

raise SystemExit(1 if failed else 0)
PY_QUAY_DIAGNOSTICS
fi

# Copy JUnit XMLs to SHARED_DIR for cross-step summary aggregation
cp "${ARTIFACT_DIR}"/junit-*.xml "${SHARED_DIR}/" 2>/dev/null || true

# Preserve the original test failure; otherwise fail on a credential mismatch.
if [[ "${test_status}" -ne 0 ]]; then
  exit "${test_status}"
fi
exit "${diagnostic_status}"
